<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {ElMessage} from 'element-plus'
import Chart from '../components/Chart.vue'
import {api} from '../api'
type Weather={source:string;source_url:string;fetched_at:string;cached:boolean;current:{temperature_2m:number;relative_humidity_2m:number;precipitation:number;wind_speed_10m:number;time:string};daily:{time:string[];temperature_2m_max:number[];temperature_2m_min:number[];precipitation_probability_max:number[]}}
const latitude=ref(30.27),longitude=ref(120.15),data=ref<Weather>(),busy=ref(false),error=ref('')
async function load(){busy.value=true;error.value='';try{data.value=await api(`/weather?latitude=${latitude.value}&longitude=${longitude.value}`)}catch(e){data.value=undefined;error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
const option=computed(()=>({color:['#d4a64d','#246b47'],tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:40,right:35,top:30,bottom:55},xAxis:{type:'category',data:data.value?.daily.time},yAxis:{type:'value',name:'℃'},series:[{name:'最高温度',type:'line',data:data.value?.daily.temperature_2m_max},{name:'最低温度',type:'line',data:data.value?.daily.temperature_2m_min}]}))
</script>
<template><div class="page-title"><div><h1>天气中心</h1><p>真实天气服务与 Redis 缓存 · 默认杭州位置，可修改经纬度</p></div></div><section class="panel"><div class="toolbar"><label>纬度 <el-input-number v-model="latitude" :min="18" :max="54" :precision="3"/></label><label>经度 <el-input-number v-model="longitude" :min="73" :max="135" :precision="3"/></label><el-button type="primary" :loading="busy" @click="load">查询天气</el-button><el-tag v-if="data" :type="data.cached?'info':'success'">{{data.cached?'缓存命中':'实时请求'}}</el-tag></div><el-alert v-if="error" :title="error" type="error" :closable="false"/></section><template v-if="data"><div class="metrics"><div class="metric"><div class="metric-label">室外温度</div><div class="metric-value">{{data.current.temperature_2m}} ℃</div></div><div class="metric"><div class="metric-label">室外湿度</div><div class="metric-value">{{data.current.relative_humidity_2m}} %</div></div><div class="metric"><div class="metric-label">降水</div><div class="metric-value">{{data.current.precipitation}} mm</div></div><div class="metric"><div class="metric-label">风速</div><div class="metric-value">{{data.current.wind_speed_10m}} km/h</div></div></div><section class="panel"><h2>未来七天气温预报</h2><Chart :option="option as never"/><p class="muted">来源：<a :href="data.source_url" target="_blank" rel="noopener noreferrer">{{data.source}}</a> · 数据时间 {{data.current.time}} · 获取时间 {{data.fetched_at}}。室外天气不能替代田间或温室实测。</p></section></template></template>
